import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.CpZKh-tG.js";const u=JSON.parse('{"title":"Build / CI / Deploy tooling","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tooling/build-ci-deploy.md","filePath":"reference/tooling/build-ci-deploy.md"}'),c={name:"reference/tooling/build-ci-deploy.md"};function d(n,e,a,i,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="build-ci-deploy-tooling" tabindex="-1">Build / CI / Deploy tooling <a class="header-anchor" href="#build-ci-deploy-tooling" aria-label="Permalink to &quot;Build / CI / Deploy tooling&quot;">​</a></h1><p>Reference for the durable build, lint, test, release, and deploy tooling in Orrery — the npm meta-targets in <code>package.json</code> and the scripts under <code>scripts/</code> they wrap, plus the GitHub Actions workflows in <code>.github/workflows/</code>. This is a catalogue, not a tutorial: for the <em>why</em> behind the asset/provenance pipelines see <a href="./../../adr/TA#pipelines">TA.md §pipelines</a>, and for the day-to-day push discipline see <a href="./../../../AGENTS">AGENTS.md §&quot;Preflight before push&quot;</a>.</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Command</th><th>When</th></tr></thead><tbody><tr><td>Build</td><td><code>npm run build</code></td><td>Produce the static <code>build/</code> bundle (prerendered, pruned, verified)</td></tr><tr><td>Preview</td><td><code>npm run preview</code></td><td>Serve <code>build/</code> locally via vite preview</td></tr><tr><td>Typecheck / check</td><td><code>npm run typecheck</code> / <code>npm run check</code></td><td>svelte-check over the tree</td></tr><tr><td>Lint</td><td><code>npm run lint</code> (<code>:prettier</code>, <code>:eslint</code>)</td><td>Format + lint gate</td></tr><tr><td>Format</td><td><code>npm run format</code></td><td>Write prettier fixes</td></tr><tr><td>Unit test</td><td><code>npm run test</code> (<code>:coverage</code>)</td><td>vitest run</td></tr><tr><td>E2e</td><td><code>npm run test:e2e</code> / <code>:e2e:smoke</code></td><td>Playwright against built bundle</td></tr><tr><td>Preflight</td><td><code>npm run preflight</code> / <code>:full</code> / <code>ci</code></td><td>Pre-push gate (smart subset / full)</td></tr><tr><td>Secret scan</td><td><code>npm run check-no-secrets</code> (<code>:all</code>)</td><td>Credential-pattern gate</td></tr><tr><td>Release rehearsal</td><td><code>npm run release:rehearsal vX.Y.Z</code></td><td>Pre-tag full-gate dry run</td></tr><tr><td>Linux baselines</td><td><code>npm run regen-visual-baselines-linux</code></td><td>Regenerate CI-matching visual PNGs</td></tr><tr><td>Screenshots</td><td><code>npm run screenshots</code></td><td>README / guide screenshots</td></tr><tr><td>Colophon thumbs</td><td><code>tsx scripts/capture-colophon-thumbs.ts</code></td><td>/colophon WebP thumbnails</td></tr><tr><td>Mockups</td><td><code>node scripts/mockups/render-*.mjs</code></td><td>Slice-0 visual previews (docs)</td></tr><tr><td>Docker</td><td><code>npm run docker:*</code></td><td>Local compose stack + pipeline-runner</td></tr><tr><td>Deploy prod</td><td><code>gh workflow run &quot;Deploy to prod VPS (orrery)&quot;</code></td><td>Manual VPS deploy</td></tr><tr><td>Deploy preview</td><td>auto on docker-e2e green / <code>gh workflow run &quot;Deploy preview&quot;</code></td><td>GH Pages app+docs publish</td></tr></tbody></table><hr><h2 id="npm-run-build" tabindex="-1"><code>npm run build</code> <a class="header-anchor" href="#npm-run-build" aria-label="Permalink to &quot;`npm run build`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run build</code><strong>What</strong> — Full static build chain: <code>i18n:compile → validate-data → build-science-index → precompute-porkchops → vite build → prune-build-staging → check-prerender-completeness</code>. Emits <code>build/</code> (the deploy unit). <strong>When</strong> — Inside preflight, before e2e, in every deploy workflow, before screenshots. <strong>I/O</strong> — Writes <code>build/</code>; reads <code>static/data/</code>, <code>messages/</code>, <code>project.inlang/</code>. <strong>Gotchas</strong> — Two post-build guards run <em>after</em> <code>vite build</code> and can fail a build that otherwise compiled clean (see prune + prerender sections). <code>VITE_BASE=/orrery/</code> switches on the GH Pages subdirectory mount (see <code>gh-pages-compat.mjs</code>). <strong>State</strong> — healthy.</p><h2 id="npm-run-preview-check-typecheck" tabindex="-1"><code>npm run preview</code> / <code>check</code> / <code>typecheck</code> <a class="header-anchor" href="#npm-run-preview-check-typecheck" aria-label="Permalink to &quot;`npm run preview` / `check` / `typecheck`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run preview</code> | <code>npm run check</code> | <code>npm run typecheck</code><strong>What</strong> — <code>preview</code> = <code>vite preview</code> over <code>build/</code>. <code>check</code> and <code>typecheck</code> are identical: <code>i18n:compile → svelte-kit sync → svelte-check</code>. <strong>When</strong> — <code>preview</code> for eyeballing a prod bundle; <code>typecheck</code> in preflight. <strong>Gotchas</strong> — <code>preview</code> does not build; run <code>npm run build</code> first. <strong>State</strong> — healthy. Opportunity: <code>check</code> and <code>typecheck</code> are byte-identical scripts — one could alias the other.</p><h2 id="lint-format" tabindex="-1">Lint / format <a class="header-anchor" href="#lint-format" aria-label="Permalink to &quot;Lint / format&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run lint</code> (= <code>lint:prettier</code> + <code>lint:eslint</code>), <code>npm run format</code><strong>What</strong> — <code>lint:prettier</code> = <code>prettier --check --cache .</code>; <code>lint:eslint</code> = eslint with a cache at <code>node_modules/.cache/eslint-cache</code>; <code>format</code> = <code>prettier --write .</code>. <strong>When</strong> — In preflight; <code>format</code> before committing. <strong>Gotchas</strong> — Some Claude Code sessions rewrite prettier <code>[warn]</code> output to a false &quot;all formatted&quot; line while still exiting 1 — trust the exit code (CLAUDE.md §&quot;Bash output filtering&quot;). <strong>State</strong> — healthy.</p><h2 id="test-test-test-coverage-test-e2e-test-e2e-smoke" tabindex="-1">Test (<code>test</code>, <code>test:coverage</code>, <code>test:e2e</code>, <code>test:e2e:smoke</code>) <a class="header-anchor" href="#test-test-test-coverage-test-e2e-test-e2e-smoke" aria-label="Permalink to &quot;Test (`test`, `test:coverage`, `test:e2e`, `test:e2e:smoke`)&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run test</code> | <code>test:coverage</code> | <code>test:e2e</code> | <code>test:e2e:smoke</code><strong>What</strong> — <code>test</code> = <code>vitest run --passWithNoTests</code>. <code>:coverage</code> adds v8 coverage. <code>:e2e</code> = <code>npm run build &amp;&amp; playwright test</code> (all projects). <code>:e2e:smoke</code> = build + <code>--workers=1 --project=desktop-chromium</code> over <code>landing.spec.ts</code> + <code>smoke.spec.ts</code>. <strong>When</strong> — <code>test</code> in preflight; e2e before tagging (both <code>desktop-chromium</code> AND <code>mobile-chromium</code>); smoke for a fast sanity check. <strong>Gotchas</strong> — Always pass <code>--workers=1</code> for e2e: the shared vite preview server crashes under the default 2 workers. Preflight does NOT run e2e. <strong>State</strong> — healthy.</p><h2 id="npm-run-preflight-→-scripts-preflight-smart-mjs" tabindex="-1"><code>npm run preflight</code> → <code>scripts/preflight-smart.mjs</code> <a class="header-anchor" href="#npm-run-preflight-→-scripts-preflight-smart-mjs" aria-label="Permalink to &quot;`npm run preflight` → `scripts/preflight-smart.mjs`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run preflight</code> (= <code>with-lock preflight -- node scripts/preflight-smart.mjs</code>). <code>npm run ci</code> aliases it. <strong>What</strong> — Smart runner: <code>git fetch origin main</code>, diffs <code>origin/main...HEAD</code> + working tree, categorizes changed paths, and runs only the relevant check subset. Routing: docs-only → secret scan; data-only → validate-data + build; messages-only → i18n + typecheck + build; audio-only → audio cost + build; tests-only → vitest <code>--changed</code> + build; source-code → typecheck + lint + vitest <code>--changed</code> + validate-data + secrets + build; static-asset-only → build. Any config-file or unrecognised path → FULL. <strong>When</strong> — Pre-push gate (husky <code>pre-push</code> auto-runs it). Mirrors CI. <strong>I/O</strong> — Reads git diff; strips generated <code>src/lib/paraglide/</code> from the change set. <strong>Gotchas</strong> — Pre-push gate, NOT a mid-iteration checkpoint. Does NOT run e2e (release rehearsal covers that). Set <code>PREFLIGHT_OFFLINE=1</code> to skip <code>git fetch</code> on no-network runners. In <code>bash -c</code> wrappers always <code>set -o pipefail</code> before reading <code>EXIT=$?</code> after <code>| tail</code>. <strong>State</strong> — healthy.</p><h2 id="npm-run-preflight-full" tabindex="-1"><code>npm run preflight:full</code> <a class="header-anchor" href="#npm-run-preflight-full" aria-label="Permalink to &quot;`npm run preflight:full`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run preflight:full</code> (= <code>with-lock preflight -- npm run preflight:full:body</code>) <strong>What</strong> — Unconditional full chain: <code>typecheck → lint → test → validate-data → audio:check-cost → check-no-secrets:all → build</code>. The smart runner&#39;s <code>full</code> mode dispatches to the same <code>preflight:full:body</code>. <strong>When</strong> — Manual escape hatch when you don&#39;t trust the smart subset. <strong>State</strong> — healthy.</p><h2 id="scripts-with-lock-mjs" tabindex="-1"><code>scripts/with-lock.mjs</code> <a class="header-anchor" href="#scripts-with-lock-mjs" aria-label="Permalink to &quot;`scripts/with-lock.mjs`&quot;">​</a></h2><p><strong>Command</strong> — <code>node scripts/with-lock.mjs &lt;name&gt; -- &lt;command&gt; [args...]</code><strong>What</strong> — POSIX file mutex (atomic <code>mkdir</code> at <code>$TMPDIR/orrery-&lt;name&gt;.lock</code>) around a child command. Prevents two concurrent <code>preflight</code>/<code>build</code> runs from racing on <code>.svelte-kit/output</code> rimraf (the <code>ENOTEMPTY</code> phantom failure). Writes <code>{pid,ts,cmd}</code> for diagnosis; auto-clears stale locks (&gt;30 min); bounded 1 h wait then exits 124. <strong>When</strong> — Wraps both preflight targets. Reusable for any tool that writes <code>.svelte-kit/</code>, <code>node_modules/.vite</code>, or <code>build/</code>. <strong>Gotchas</strong> — SIGKILL/crash leaves a lock the next acquire clears as stale. <strong>State</strong> — healthy.</p><h2 id="scripts-prune-build-staging-mjs" tabindex="-1"><code>scripts/prune-build-staging.mjs</code> <a class="header-anchor" href="#scripts-prune-build-staging-mjs" aria-label="Permalink to &quot;`scripts/prune-build-staging.mjs`&quot;">​</a></h2><p><strong>Command</strong> — runs in <code>npm run build</code> (<code>node scripts/prune-build-staging.mjs</code>) <strong>What</strong> — adapter-static copies all of <code>static/</code> into <code>build/</code>, including the gitignored <code>build/images/_staging</code> review scratch area. This removes it, then walks <code>build/</code> to assert no <code>_staging</code> survived — a leak fails the build. <strong>When</strong> — Post-<code>vite build</code>, automatically. <strong>I/O</strong> — Deletes <code>build/images/_staging</code>. <strong>State</strong> — healthy.</p><h2 id="scripts-check-prerender-completeness-mjs" tabindex="-1"><code>scripts/check-prerender-completeness.mjs</code> <a class="header-anchor" href="#scripts-check-prerender-completeness-mjs" aria-label="Permalink to &quot;`scripts/check-prerender-completeness.mjs`&quot;">​</a></h2><p><strong>Command</strong> — runs in <code>npm run build</code><strong>What</strong> — Post-build guardrail against silent prerender drops (the #342 regression where the build emitted only the en-US tree, ~18 HTML files). Asserts every non-base locale in <code>project.inlang/settings.json</code> has its root HTML and total HTML count ≥ 200. <strong>When</strong> — Post-<code>vite build</code>, automatically. <strong>I/O</strong> — Reads <code>build/</code> + <code>project.inlang/settings.json</code>. <strong>Gotchas</strong> — Floor is a coarse 200; does not check per-route × per-locale completeness (Playwright e2e covers content correctness). <strong>State</strong> — healthy.</p><h2 id="scripts-gh-pages-compat-mjs" tabindex="-1"><code>scripts/gh-pages-compat.mjs</code> <a class="header-anchor" href="#scripts-gh-pages-compat-mjs" aria-label="Permalink to &quot;`scripts/gh-pages-compat.mjs`&quot;">​</a></h2><p><strong>Command</strong> — imported by <code>vite.config.ts</code> + <code>svelte.config.js</code> (not run directly) <strong>What</strong> — GH Pages subdirectory-mount helpers, active only under <code>VITE_BASE=/orrery/</code>. <code>ghPagesUrlPatterns(base)</code> injects Paraglide <code>urlPatterns</code> so the locale matcher looks <em>after</em> the base prefix; <code>expandLocalizedRoots(routes)</code> inlines per-locale prerender entries (stable across svelte.config re-evaluation). Both return inert values when base is empty, so the VPS root-mount build is unaffected. <strong>When</strong> — Build time on the GH Pages path. <strong>Gotchas</strong> — <code>LOCALES</code> is a hand-maintained mirror of <code>project.inlang/settings.json</code>; the two must stay in sync. Delete this file + call sites when GH Pages is retired (<code>git grep gh-pages-compat</code>). <strong>State</strong> — current. Opportunity: locale list duplication is a known drift hazard.</p><h2 id="npm-run-release-rehearsal-→-scripts-release-rehearsal-ts" tabindex="-1"><code>npm run release:rehearsal</code> → <code>scripts/release-rehearsal.ts</code> <a class="header-anchor" href="#npm-run-release-rehearsal-→-scripts-release-rehearsal-ts" aria-label="Permalink to &quot;`npm run release:rehearsal` → `scripts/release-rehearsal.ts`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run release:rehearsal vX.Y.Z</code><strong>What</strong> — Codifies the AGENTS.md pre-tag checklist as one command: (0) offer to bump <code>package.json</code> + scaffold a <code>## [X.Y.Z]</code> CHANGELOG section, (1) preflight, (2) e2e <code>desktop-chromium</code>, (3) e2e <code>mobile-chromium</code>, (4) extract the CHANGELOG body via awk to <code>/tmp/release-body-vX.Y.Z.md</code>, (5) create/update a DRAFT GH Release (idempotent). <strong>When</strong> — Before tagging a release. Enforces &quot;preflight is not enough to ship&quot; (preflight excludes e2e). <strong>Gotchas</strong> — Calls playwright directly with <code>--workers=1</code> to avoid the <code>test:e2e</code> double-build. Auto-fix prompts are skipped in non-TTY/CI. Step 5 skips gracefully if <code>gh</code> is unauthenticated. <strong>State</strong> — needs-attention: <code>changelogPath</code> is declared with <code>const</code> twice (Step 0 line ~123 and Step 4 line ~180) — a redeclaration in module scope. De-dupe to the top.</p><h2 id="npm-run-regen-visual-baselines-linux-→-scripts-regenerate-visual-baselines-linux-sh" tabindex="-1"><code>npm run regen-visual-baselines-linux</code> → <code>scripts/regenerate-visual-baselines-linux.sh</code> <a class="header-anchor" href="#npm-run-regen-visual-baselines-linux-→-scripts-regenerate-visual-baselines-linux-sh" aria-label="Permalink to &quot;`npm run regen-visual-baselines-linux` → `scripts/regenerate-visual-baselines-linux.sh`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run regen-visual-baselines-linux</code><strong>What</strong> — Regenerates <code>tests/e2e/visual.spec.ts</code> baselines inside the official <code>mcr.microsoft.com/playwright:v&lt;ver&gt;-noble</code> image (pixel-matches the CI ubuntu runner). Caches Linux <code>node_modules</code> in <code>.linux-node-modules/</code> (gitignored) so the host darwin tree is untouched; builds, then runs visual.spec with <code>--update-snapshots</code>. <strong>When</strong> — Whenever a /credits, /library, or /science header layout changes — regen the darwin baselines in the SAME commit so the two never diverge. <strong>I/O</strong> — Writes <code>tests/e2e/visual.spec.ts-snapshots/</code>. <strong>Gotchas</strong> — Requires Docker (~1.2 GB first pull). Pins the image to the <code>@playwright/test</code> devDependency version; <code>npm ci</code> uses <code>--ignore-scripts</code> (gdal/sharp native builds fail in the playwright image and aren&#39;t needed for visuals). <strong>State</strong> — healthy.</p><h2 id="npm-run-screenshots-→-scripts-capture-screenshots-ts" tabindex="-1"><code>npm run screenshots</code> → <code>scripts/capture-screenshots.ts</code> <a class="header-anchor" href="#npm-run-screenshots-→-scripts-capture-screenshots-ts" aria-label="Permalink to &quot;`npm run screenshots` → `scripts/capture-screenshots.ts`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run screenshots</code> (= build + <code>tsx scripts/capture-screenshots.ts</code>) <strong>What</strong> — Spawns its own <code>vite preview</code> (port 4173) and drives Chromium serially through the <code>SHOTS</code> array (every route + interaction state) into committed <code>docs/screenshots/</code> PNGs. <strong>When</strong> — When a showcased screen/interaction changes. Add a <code>Shot</code> entry for new states. <strong>I/O</strong> — Writes <code>docs/screenshots/</code>. <strong>Gotchas</strong> — Serial by design for determinism; uses <code>reducedMotion: &#39;reduce&#39;</code> to freeze simT. <strong>State</strong> — healthy.</p><h2 id="scripts-capture-colophon-thumbs-ts" tabindex="-1"><code>scripts/capture-colophon-thumbs.ts</code> <a class="header-anchor" href="#scripts-capture-colophon-thumbs-ts" aria-label="Permalink to &quot;`scripts/capture-colophon-thumbs.ts`&quot;">​</a></h2><p><strong>Command</strong> — <code>BASE=http://localhost:5373 npx tsx scripts/capture-colophon-thumbs.ts</code> (env: <code>SUBSET=models|scenes|all</code>) <strong>What</strong> — Captures the 800×560 WebP thumbnails the /colophon page shows for live-rendered 3D models (<code>/dev/models</code>) + procedural scene overlays, encoded via sharp. <strong>When</strong> — When colophon model/scene thumbnails need refreshing. <strong>I/O</strong> — Writes <code>static/images/colophon/</code>. <strong>Gotchas</strong> — Connects to an ALREADY-RUNNING dev server (does not spawn one) — never kill Marko&#39;s :5373. Hides site nav/footer before capture. <strong>State</strong> — healthy.</p><h2 id="npm-run-check-no-secrets-all-→-scripts-check-no-secrets-ts" tabindex="-1"><code>npm run check-no-secrets</code> (<code>:all</code>) → <code>scripts/check-no-secrets.ts</code> <a class="header-anchor" href="#npm-run-check-no-secrets-all-→-scripts-check-no-secrets-ts" aria-label="Permalink to &quot;`npm run check-no-secrets` (`:all`) → `scripts/check-no-secrets.ts`&quot;">​</a></h2><p><strong>Command</strong> — <code>npm run check-no-secrets</code> (staged diff) / <code>check-no-secrets:all</code> (full tree) <strong>What</strong> — Fail-closed regex sweep for credential shapes (Sentry DSN, Grafana <code>glc_</code>, Anthropic <code>sk-ant-</code>). Staged-diff mode for pre-commit/preflight; <code>--all</code> (<code>git ls-files</code>) for CI. Allowlist: <code>.env.example</code>, <code>docs/**</code>, <code>*.test.ts</code>/<code>*.spec.ts</code>, and the script itself. <strong>When</strong> — In preflight (<code>:all</code>) and the husky pre-commit hook. <strong>Exit</strong> — 0 clean, 1 match, 2 invocation error. <strong>Gotchas</strong> — Do not <code>--no-verify</code> past a hit — rotate the credential first. <strong>State</strong> — healthy.</p><h2 id="scripts-check-no-secrets-in-image-sh" tabindex="-1"><code>scripts/check-no-secrets-in-image.sh</code> <a class="header-anchor" href="#scripts-check-no-secrets-in-image-sh" aria-label="Permalink to &quot;`scripts/check-no-secrets-in-image.sh`&quot;">​</a></h2><p><strong>Command</strong> — <code>scripts/check-no-secrets-in-image.sh &lt;image-tag&gt;</code><strong>What</strong> — Complement to the source scanner: scans a built Docker image&#39;s <em>filesystem</em> for secret-pattern files (<code>.env</code>, <code>*.key</code>, <code>*.pem</code>, <code>id_rsa</code>, <code>credentials</code>, …) via <code>docker run … find</code>. Belt-and-suspenders against <code>.dockerignore</code> drift. Excludes CA bundles, <code>/proc</code>, <code>/sys</code>, and <code>node_modules</code> (public npm test fixtures). <strong>When</strong> — The docker-e2e <code>publish</code> job, before pushing to GHCR. <strong>Exit</strong> — 0 clean, 1 usage error, 2 secrets found (blocks publish). <strong>State</strong> — healthy.</p><h2 id="mockup-renderers-scripts-mockups-render-mjs" tabindex="-1">Mockup renderers (<code>scripts/mockups/render-*.mjs</code>) <a class="header-anchor" href="#mockup-renderers-scripts-mockups-render-mjs" aria-label="Permalink to &quot;Mockup renderers (`scripts/mockups/render-*.mjs`)&quot;">​</a></h2><p><strong>Command</strong> — <code>node scripts/mockups/render-surface-mockups.mjs</code> / <code>node scripts/mockups/render-panorama-redesign.mjs</code><strong>What</strong> — One-off Slice-0 visual-preview generators. <code>render-surface-mockups</code> writes 12 surface-redesign frames (Mars + Moon × 6 zoom states, #283) into <code>docs/mockups/surface-redesign/</code>; <code>render-panorama-redesign</code> writes 8 Tier-3 panorama frames (#286 / ADR-074) into <code>docs/mockups/panorama-redesign/</code>. Both composite real textures/panoramas under schematic SVG via Playwright at 1920×1080. <strong>When</strong> — Visual-anchor step for a UX redesign, gated on Marko&#39;s approval (per the &quot;visual anchor before UX commit&quot; pattern). Not part of build/CI. <strong>I/O</strong> — Read <code>static/textures/</code> and <code>static/images/hotspots/</code>; write <code>docs/mockups/</code>. <strong>Gotchas</strong> — <code>render-panorama-redesign</code> copies panoramas to temp files (Chromium silently fails on data URLs &gt;256 KB) and cleans up <code>_bg_*.jpg</code> after. <strong>State</strong> — current (issue-scoped). Opportunity: candidates for archival once #283/#286 ship.</p><h2 id="docker-targets-npm-run-docker" tabindex="-1">Docker targets (<code>npm run docker:*</code>) <a class="header-anchor" href="#docker-targets-npm-run-docker" aria-label="Permalink to &quot;Docker targets (`npm run docker:*`)&quot;">​</a></h2><p><strong>Command</strong> — <code>docker:build</code> | <code>up</code> (web -d) | <code>down</code> | <code>logs</code> (web -f) | <code>reset-data</code> (rm <code>orrery-data</code>/<code>orrery-cache</code> volumes). Pipeline-runner one-shots: <code>docker:fetch-launches</code>, <code>docker:images:hotspots</code>, <code>docker:fetch-assets</code>, <code>docker:validate-data</code>, <code>docker:build-image-provenance</code>, <code>docker:build-link-provenance</code>, <code>docker:audit-launches</code>. <strong>What</strong> — Wrap <code>docker compose</code> for the local stack; the <code>pipeline-runner</code> targets run a data script once in the runner container (<code>docker compose run --rm pipeline-runner …</code>). <strong>When</strong> — Local reproduction of the prod serving shape (cache headers, CSP, brotli/gzip, SPA fallback) and offline-safe pipeline runs. <strong>Gotchas</strong> — <code>docker:reset-data</code> is destructive (drops named volumes). <strong>State</strong> — healthy.</p><hr><h2 id="deploy-—-github-actions-workflows" tabindex="-1">Deploy — GitHub Actions workflows <a class="header-anchor" href="#deploy-—-github-actions-workflows" aria-label="Permalink to &quot;Deploy — GitHub Actions workflows&quot;">​</a></h2><p>The deploy chain is <code>ci.yml → docker-e2e.yml → preview.yml</code>, with <code>deploy-docs.yml</code> branching off CI directly and prod/release as separate manual/tag triggers.</p><h3 id="deploy-preview-preview-yml-—-gh-pages-app-docs" tabindex="-1">Deploy preview (<code>preview.yml</code>) — GH Pages app + docs <a class="header-anchor" href="#deploy-preview-preview-yml-—-gh-pages-app-docs" aria-label="Permalink to &quot;Deploy preview (`preview.yml`) — GH Pages app + docs&quot;">​</a></h3><p><strong>Trigger</strong> — <code>workflow_run</code> on <strong>docker-e2e</strong> completion (success only, branch main); also <code>workflow_dispatch</code> and a weekly Monday 06:00 UTC cron (fresh imagery, ADR-016). <strong>What</strong> — Builds with <code>VITE_BASE=/orrery/</code> + <code>npm run docs:build</code> (<code>DOCS_BASE=/orrery/docs/</code>), copies docs into <code>build/docs</code>, publishes the full <code>build/</code> to the <code>gh-pages</code> branch. <strong>Manual</strong> — <code>gh workflow run &quot;Deploy preview&quot; --ref main</code> (force-publish when the e2e gate blocked the auto-deploy). <strong>Gotchas</strong> — Deploys the exact SHA that passed docker-e2e. Shares concurrency group <code>gh-pages-publish</code> with deploy-docs (serialized, no cancel-in-progress).</p><h3 id="deploy-docs-deploy-docs-yml-—-docs-only" tabindex="-1">Deploy docs (<code>deploy-docs.yml</code>) — docs-only <a class="header-anchor" href="#deploy-docs-deploy-docs-yml-—-docs-only" aria-label="Permalink to &quot;Deploy docs (`deploy-docs.yml`) — docs-only&quot;">​</a></h3><p><strong>Trigger</strong> — <code>workflow_run</code> on <strong>CI</strong> success (branch main), plus <code>workflow_dispatch</code>. Independent of e2e so docs fixes ship even when the app e2e suite is red (ADR-070). <strong>What</strong> — Builds VitePress and publishes only <code>docs/.vitepress/dist</code> to <code>gh-pages</code> under <code>docs/</code> with <code>keep_files: true</code> (overlay — leaves the app bundle intact). <strong>Manual</strong> — <code>gh workflow run &quot;Deploy docs&quot; --ref main</code>. <strong>Gotchas</strong> — Needs <code>npm run i18n:compile</code> + <code>npx svelte-kit sync</code> before <code>docs:build</code> (both generate files svelte.config/tsconfig import but <code>npm ci</code> doesn&#39;t produce).</p><h3 id="deploy-to-prod-vps-deploy-prod-yml" tabindex="-1">Deploy to prod VPS (<code>deploy-prod.yml</code>) <a class="header-anchor" href="#deploy-to-prod-vps-deploy-prod-yml" aria-label="Permalink to &quot;Deploy to prod VPS (`deploy-prod.yml`)&quot;">​</a></h3><p><strong>Trigger</strong> — <code>workflow_dispatch</code> only, with optional <code>override_image_sha</code> input (blank = <code>:main</code> image tag; the deployed app code is always main HEAD). <strong>What</strong> — Builds the static bundle in CI (with <code>PUBLIC_SENTRY_*</code>), joins the tailnet via Tailscale, rsyncs <code>build/</code> to <code>/srv/orrery/build/</code> on the Hetzner VPS, stages <code>.env</code> from <code>prod</code>-scoped secrets, then SSHes to <code>git fetch+reset → docker compose pull/build/up</code> (web + grafana-agent) and health-probes loopback + tailnet. <strong>Manual</strong> — <code>gh workflow run &quot;Deploy to prod VPS (orrery)&quot;</code> (optionally <code>-f override_image_sha=&lt;7-char&gt;</code> for pipeline-runner rollback). <strong>Gotchas</strong> — Skips gracefully (warning, green) if <code>TS_AUTHKEY</code> / <code>PROD_SSH_PRIVATE_KEY</code> / <code>PROD_TAILNET_FQDN</code> are unset. <code>override_image_sha</code> only affects the <code>pipeline-runner</code> image (profile: manual), not the served app. Bootstrap (initial clone) is owned by podcast_scraper cloud-init, not this workflow.</p><h3 id="auto-publish-gh-release-on-tag-push-release-yml" tabindex="-1">Auto-publish GH Release on tag push (<code>release.yml</code>) <a class="header-anchor" href="#auto-publish-gh-release-on-tag-push-release-yml" aria-label="Permalink to &quot;Auto-publish GH Release on tag push (`release.yml`)&quot;">​</a></h3><p><strong>Trigger</strong> — <code>push</code> of a <code>v*</code> tag. <strong>What</strong> — Extracts the <code>## [X.Y.Z]</code> CHANGELOG section (same awk recipe as release-rehearsal) and creates/updates a GitHub Release. Stable tags get <code>--latest</code>; <code>vX.Y.Z-rc1</code>-style tags get <code>--prerelease</code>. Idempotent. <strong>Gotchas</strong> — Publishes the <em>tagged</em> commit&#39;s CHANGELOG, not main HEAD. Does NOT trigger the Pages deploy (that chains through ci → docker-e2e → preview). Fails if the CHANGELOG section is missing — add it, retag, push.</p>',52)])])}const g=o(c,[["render",d]]);export{u as __pageData,g as default};
